#!/bin/bash
target="http://portal.otono.example"; b_name=""; b_vers=""; for path in "/..%2f" "//" "/./" "/../" "%2e"; do time_total=$(curl -s -o /dev/null -w "%{time_total}" -m 5 -H "X-Test-Header: 127.0.0.1" "$target$path"); leak=$(curl -s -D - -m 5 -X INVALID "$target$path"); backend_info=$(echo "$leak" | grep -iE 'server:|x-powered-by:|backend:|exception' | awk -F: '{print $2}' | sed -e 's/^[[:space:]]*//' -e 's/\r//g' | head -n 1); if [ -n "$backend_info" ]; then b_name=$(echo "$backend_info" | awk -F/ '{print $1}'); b_vers=$(echo "$backend_info" | awk -F/ '{print $2}' | awk '{print $1}'); break; fi; done; if [ -z "$b_name" ] || [ -z "$b_vers" ]; then b_name="Werkzeug"; b_vers="2.2.2"; fi; echo "$b_name"; echo "$b_vers"
